{
  "status": "SUPPORTED",
  "task_summary": "Find compatible parts and tools in storage, fasten a component at the workbench, and return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "assembly_component",
        "entity_kind": "OBJECT",
        "function": "The object that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["yellow block", "blue block", "assembly"],
        "required_properties": ["needs fastening"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to secure the component.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "clamp", "wrench", "tool"],
        "required_properties": ["capable of fastening"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The flat surface where fastening occurs.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "workbench"],
        "required_properties": ["flat surface"]
      },
      {
        "id": "storage_container",
