        "function": "Enclosed spaces to search for tools or parts.",
        "required_count": 3,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cabinet", "drawer"],
        "required_properties": ["enclosed", "openable"]
      },
      {
        "id": "robot_manipulator",
        "entity_kind": "OBJECT",
        "function": "The agent performing the task actions.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["robot arm", "manipulator"],
        "required_properties": ["mobile", "dexterous"]
      }
    ],
