        "participant_roles": ["assembly_component", "fastening_tool"]
      ,
      "required": true
      },
      {
        "id": "secured_fastening",
        "relation": "The component must be fastened at the workbench location.",
        "participant_roles": ["assembly_component", "workbench_surface"]
      ,
      "required": true
      },
      {
        "id": "returned_tool_placement",
        "relation": "The tool must be placed on the workbench after use.",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "inspect_storage",
        "operation": "Search storage containers for the tool or components.",
        "participant_roles": ["robot_manipulator", "storage_container"]
      ,
      "operation_count": 3
      },
      {
        "id": "perform_fastening",
        "operation": "Use the tool to fasten the component at the workbench.",
        "participant_roles": ["robot_manipulator", "assembly_component", "fastening_tool"]
      ,
      "operation_count": 1
      },
      {
        "id": "deposit_tool",
        "operation": "Place the tool on the workbench.",
        "participant_roles": ["robot_manipulator", "fastening_tool", "workbench_surface"]
      ,
      "operation_count": 1
      }
    ]
  },
